package com.foodieexpress.service;
import com.foodieexpress.dto.*;import com.foodieexpress.model.*;import com.foodieexpress.repository.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service public class SupportService {
 private final SupportTicketRepository tickets;private final SupportMessageRepository messages;private final SupportTicketEventRepository events;private final FaqEntryRepository faqs;private final OrderRepository orders;private final UserRepository users;
 public SupportService(SupportTicketRepository t,SupportMessageRepository m,SupportTicketEventRepository e,FaqEntryRepository f,OrderRepository o,UserRepository u){tickets=t;messages=m;events=e;faqs=f;orders=o;users=u;}
 public List<SupportResponses.Faq> searchFaq(String query,FaqEntry.Category category){String q=query==null?"":query.trim().toLowerCase(Locale.ROOT);return faqs.findByActiveTrueOrderByCategoryAscIdAsc().stream().filter(f->category==null||f.getCategory()==category).filter(f->q.isEmpty()||f.getQuestion().toLowerCase(Locale.ROOT).contains(q)||f.getAnswer().toLowerCase(Locale.ROOT).contains(q)).map(this::faqDto).toList();}
 @Transactional public List<SupportResponses.Faq> adminFaqs(){return faqs.findAllByOrderByCategoryAscIdAsc().stream().map(this::faqDto).toList();}
 @Transactional public SupportResponses.Faq saveFaq(Long id,SupportRequests.Faq req){FaqEntry f=id==null?new FaqEntry():faqs.findById(id).orElseThrow(()->new RuntimeException("FAQ not found"));f.setCategory(req.category());f.setQuestion(clean(req.question(),240));f.setAnswer(clean(req.answer(),5000));f.setActive(req.active()==null||req.active());return faqDto(faqs.save(f));}
 @Transactional public void deleteFaq(Long id){FaqEntry faq=faqs.findById(id).orElseThrow(()->new RuntimeException("FAQ not found"));faq.setActive(false);faqs.save(faq);}
 @Transactional public SupportResponses.Ticket create(Customer customer,SupportRequests.CreateTicket req){Order order=null;if(req.orderId()!=null){order=orders.findById(req.orderId()).orElseThrow(()->new RuntimeException("Order not found"));if(!order.getCustomer().getId().equals(customer.getId()))throw new RuntimeException("You can only reference your own orders");}
  SupportTicket t=SupportTicket.builder().customer(customer).order(order).category(req.category()).subject(clean(req.subject(),120)).description(clean(req.description(),3000)).status(SupportTicket.Status.OPEN).build();t=tickets.save(t);addMessage(t,customer.getUser(),t.getDescription());statusEvent(t,customer.getUser(),null,SupportTicket.Status.OPEN,"Ticket created");return ticketDto(t);}
 @Transactional(readOnly=true) public List<SupportResponses.Ticket> customerTickets(Customer c){return tickets.findByCustomerOrderByUpdatedAtDesc(c).stream().map(this::ticketDto).toList();}
 @Transactional(readOnly=true) public SupportResponses.Ticket customerTicket(Customer c,Long id){SupportTicket t=getTicket(id);assertOwner(c,t);return ticketDto(t);}
 @Transactional public SupportResponses.Ticket customerReply(Customer c,Long id,String body){SupportTicket t=getTicket(id);assertOwner(c,t);if(t.getStatus()==SupportTicket.Status.RESOLVED){change(t,SupportTicket.Status.OPEN,c.getUser(),"Customer replied; ticket reopened");}else if(t.getStatus()==SupportTicket.Status.WAITING_FOR_CUSTOMER){change(t,SupportTicket.Status.IN_PROGRESS,c.getUser(),"Customer replied");}addMessage(t,c.getUser(),body);return ticketDto(t);}
 @Transactional(readOnly=true) public List<SupportResponses.Ticket> adminTickets(SupportTicket.Status status,String search){String normalized=search==null||search.isBlank()?null:search.trim().toLowerCase(Locale.ROOT);Long ticketId=null;if(normalized!=null&&normalized.matches("#?\\d+")){try{ticketId=Long.parseLong(normalized.replace("#",""));}catch(NumberFormatException ignored){}}return tickets.searchAdmin(status,normalized,ticketId).stream().map(this::ticketDto).toList();}
 @Transactional(readOnly=true) public SupportResponses.Ticket adminTicket(Long id){return ticketDto(getTicket(id));}
 @Transactional public SupportResponses.Ticket adminReply(Long id,User admin,String body){SupportTicket t=getTicket(id);if(t.getStatus()!=SupportTicket.Status.WAITING_FOR_CUSTOMER&&t.getStatus()!=SupportTicket.Status.RESOLVED)change(t,SupportTicket.Status.WAITING_FOR_CUSTOMER,admin,"Admin replied");else if(t.getStatus()==SupportTicket.Status.RESOLVED)change(t,SupportTicket.Status.WAITING_FOR_CUSTOMER,admin,"Admin reopened and replied");addMessage(t,admin,body);return ticketDto(t);}
 @Transactional public SupportResponses.Ticket updateStatus(Long id,User admin,SupportTicket.Status status,String note){SupportTicket t=getTicket(id);if(!allowed(t.getStatus(),status))throw new RuntimeException("Invalid support status transition from "+t.getStatus()+" to "+status);change(t,status,admin,note==null?null:clean(note,500));return ticketDto(t);}
 @Transactional public SupportResponses.Ticket assign(Long id,Long adminId){SupportTicket t=getTicket(id);User admin=users.findById(adminId).orElseThrow(()->new RuntimeException("Admin user not found"));if(admin.getRole()!=User.Role.ADMIN)throw new RuntimeException("Tickets can only be assigned to admin accounts");t.setAssignedAdmin(admin);return ticketDto(tickets.save(t));}
 @Transactional(readOnly=true) public List<Map<String,Object>> admins(){return users.findAll().stream().filter(u->u.getRole()==User.Role.ADMIN).map(u->Map.<String,Object>of("id",u.getId(),"username",u.getUsername())).toList();}
 private boolean allowed(SupportTicket.Status from,SupportTicket.Status to){if(from==to)return true;return switch(from){case OPEN->to==SupportTicket.Status.IN_PROGRESS||to==SupportTicket.Status.WAITING_FOR_CUSTOMER||to==SupportTicket.Status.RESOLVED;case IN_PROGRESS->to==SupportTicket.Status.OPEN||to==SupportTicket.Status.WAITING_FOR_CUSTOMER||to==SupportTicket.Status.RESOLVED;case WAITING_FOR_CUSTOMER->to==SupportTicket.Status.IN_PROGRESS||to==SupportTicket.Status.RESOLVED;case RESOLVED->to==SupportTicket.Status.OPEN||to==SupportTicket.Status.IN_PROGRESS;};}
 private SupportTicket getTicket(Long id){return tickets.findById(id).orElseThrow(()->new RuntimeException("Support ticket not found"));}
 private void assertOwner(Customer c,SupportTicket t){if(!t.getCustomer().getId().equals(c.getId()))throw new RuntimeException("You can only access your own support tickets");}
 private void addMessage(SupportTicket t,User sender,String body){messages.save(SupportMessage.builder().ticket(t).sender(sender).body(clean(body,4000)).build());t.setUpdatedAt(java.time.LocalDateTime.now());tickets.save(t);}
 private void statusEvent(SupportTicket t,User actor,SupportTicket.Status from,SupportTicket.Status to,String note){events.save(SupportTicketEvent.builder().ticket(t).actor(actor).fromStatus(from).toStatus(to).note(note).build());}
 private void change(SupportTicket t,SupportTicket.Status status,User actor,String note){SupportTicket.Status before=t.getStatus();if(before==status)return;t.setStatus(status);tickets.save(t);statusEvent(t,actor,before,status,note);}
 private SupportResponses.Ticket ticketDto(SupportTicket t){List<SupportResponses.Message> ms=messages.findByTicketOrderByCreatedAtAsc(t).stream().map(m->new SupportResponses.Message(m.getId(),m.getSender().getUsername(),m.getSender().getRole().name(),m.getBody(),m.getCreatedAt())).toList();List<SupportResponses.Event> es=events.findByTicketOrderByCreatedAtAsc(t).stream().map(e->new SupportResponses.Event(e.getId(),e.getActor().getUsername(),e.getFromStatus(),e.getToStatus(),e.getNote(),e.getCreatedAt())).toList();return new SupportResponses.Ticket(t.getId(),t.getCustomer().getFullName(),t.getCustomer().getUser().getEmail(),t.getOrder()==null?null:t.getOrder().getId(),t.getCategory(),t.getSubject(),t.getDescription(),t.getStatus(),t.getAssignedAdmin()==null?null:t.getAssignedAdmin().getUsername(),t.getCreatedAt(),t.getUpdatedAt(),ms,es);}
 private SupportResponses.Faq faqDto(FaqEntry f){return new SupportResponses.Faq(f.getId(),f.getCategory(),f.getQuestion(),f.getAnswer(),f.isActive(),f.getUpdatedAt());}
 private String clean(String text,int max){if(text==null)throw new RuntimeException("Text is required");String s=text.replaceAll("(?is)<[^>]*>"," ").replaceAll("[\\p{Cntrl}&&[^\\r\\n\\t]]","").trim().replaceAll("[ \\t]{2,}"," ");if(s.isBlank())throw new RuntimeException("Text cannot be empty");if(s.length()>max)throw new RuntimeException("Text must be at most "+max+" characters");return s;}
}
